mapper.select:
SELECT 
FROM EDU_PLAN_MANAGER P
WHERE P.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND P.ACTIVITY <> 0

    AND P.TRAIN_TYPE_CODE IN (
        SELECT S.TRAIN_TYPE_CODE FROM EDU_SYSTEM_MANAGER S
        WHERE S.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
          AND S.TRAIN_DIFF_CODE = #{trainDiffCode, jdbcType=VARCHAR}
    )


    AND P.TRAIN_TYPE_CODE = #{trainTypeCode, jdbcType=VARCHAR}


    AND UPPER(P.COURSE_NAME_CODE) LIKE '%' || UPPER(#{courseName, jdbcType=VARCHAR}) || '%'

ORDER BY P.PLAN_NO DESC

SELECT TO_CHAR(MAX(TO_NUMBER(PERIOD_TIME)))
FROM EDU_PLAN_MANAGER
WHERE CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND ACTIVITY <> 0
  AND COURSE_NUMBER = #{courseNumber, jdbcType=VARCHAR}

mapper.update:
UPDATE EDU_BASIC_INFORMATION
   SET IMPLE_START_DATE = TO_DATE(#{planStartdate, jdbcType=VARCHAR}, 'DD/MM/YYYY'),
       IMPLE_END_DATE = TO_DATE(#{planEnddate, jdbcType=VARCHAR}, 'DD/MM/YYYY'),
       TRAIN_FORM_CODE = #{trainFormCode, jdbcType=VARCHAR},
       TRAIN_ADDRESS = #{trainAddress, jdbcType=VARCHAR}
 WHERE PLAN_NO = #{planNo, jdbcType=NUMERIC}

UPDATE EDU_PLAN_MANAGER
   SET ACTIVITY = '0'
 WHERE PLAN_NO = #{planNo, jdbcType=NUMERIC}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM EDU_TRAIN_SYLLABUS
 WHERE SYLL_NO = #{syllNo, jdbcType=NUMERIC}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

DELETE FROM EDU_TRAIN_SYLLABUS
 WHERE PLAN_NO = #{planNo, jdbcType=NUMERIC}
   AND ACTIVITY = 1
